export function deploymentHealthLabel(input: { connected: boolean; lastSeenMs: number | null; nowMs: number }): string {
  if (input.connected) return 'Connected';
  if (input.lastSeenMs === null) return 'Never connected';
  return Math.max(0, input.nowMs - input.lastSeenMs) < 30000 ? 'Recently disconnected' : 'Offline';
}
